import React, { useState, useEffect } from 'react';
import {
  View,
  Text,
  StyleSheet,
  Modal,
  TouchableOpacity,
  Image,
  ScrollView,
  ActivityIndicator,
  Dimensions,
} from 'react-native';
import * as ImageManipulator from 'expo-image-manipulator';
import { colors } from '@/styles/commonStyles';

interface Face {
  x: number;
  y: number;
  width: number;
  height: number;
}

interface FaceSelectorProps {
  visible: boolean;
  imageUri: string;
  faces: Face[];
  onSelectFace: (faceIndex: number) => void;
  onCancel: () => void;
}

interface FaceThumbnail {
  index: number;
  uri: string;
}

const THUMB_SIZE = 100;
const screenWidth = Dimensions.get('window').width;

async function cropFaceThumbnail(uri: string, face: Face): Promise<string> {
  try {
    const info = await ImageManipulator.manipulateAsync(uri, [], {
      format: ImageManipulator.SaveFormat.JPEG,
    });
    const imgWidth = info.width;
    const imgHeight = info.height;

    // Add padding around the face (20% on each side)
    const padX = face.width * 0.2;
    const padY = face.height * 0.2;

    const rawX = (face.x - padX) / 100;
    const rawY = (face.y - padY) / 100;
    const rawW = (face.width + padX * 2) / 100;
    const rawH = (face.height + padY * 2) / 100;

    const originX = Math.max(0, Math.round(rawX * imgWidth));
    const originY = Math.max(0, Math.round(rawY * imgHeight));
    const cropWidth = Math.min(imgWidth - originX, Math.round(rawW * imgWidth));
    const cropHeight = Math.min(imgHeight - originY, Math.round(rawH * imgHeight));

    const cropped = await ImageManipulator.manipulateAsync(
      uri,
      [{ crop: { originX, originY, width: cropWidth, height: cropHeight } }],
      { compress: 0.8, format: ImageManipulator.SaveFormat.JPEG }
    );
    return cropped.uri;
  } catch (err) {
    console.warn('[FaceSelector] Thumbnail crop failed:', err);
    return uri;
  }
}

export function FaceSelector({ visible, imageUri, faces, onSelectFace, onCancel }: FaceSelectorProps) {
  const [selectedFace, setSelectedFace] = useState<number | null>(null);
  const [thumbnails, setThumbnails] = useState<FaceThumbnail[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    if (!visible || !imageUri || faces.length === 0) return;

    setSelectedFace(null);
    setThumbnails([]);
    setLoading(true);

    console.log('[FaceSelector] Generating thumbnails for', faces.length, 'faces');

    Promise.all(
      faces.map(async (face, index) => {
        const uri = await cropFaceThumbnail(imageUri, face);
        return { index, uri };
      })
    )
      .then((results) => {
        console.log('[FaceSelector] Thumbnails ready:', results.length);
        setThumbnails(results);
        setLoading(false);
      })
      .catch((err) => {
        console.error('[FaceSelector] Failed to generate thumbnails:', err);
        setLoading(false);
      });
  }, [visible, imageUri, faces]);

  const handleConfirm = () => {
    if (selectedFace !== null) {
      console.log('[FaceSelector] Confirming face selection:', selectedFace);
      onSelectFace(selectedFace);
      setSelectedFace(null);
      setThumbnails([]);
    }
  };

  const handleCancelPress = () => {
    console.log('[FaceSelector] Cancelled');
    setSelectedFace(null);
    setThumbnails([]);
    onCancel();
  };

  const faceCountText = faces.length === 1 ? '1 volto rilevato' : `${faces.length} volti rilevati`;

  return (
    <Modal
      visible={visible}
      transparent
      animationType="fade"
      onRequestClose={handleCancelPress}
    >
      <View style={styles.overlay}>
        <View style={styles.content}>
          <Text style={styles.title}>Seleziona un volto</Text>
          <Text style={styles.subtitle}>
            {faceCountText}. Tocca il volto da usare per il confronto.
          </Text>

          {loading ? (
            <View style={styles.loadingContainer}>
              <ActivityIndicator color={colors.secondary} size="large" />
              <Text style={styles.loadingText}>Preparazione volti...</Text>
            </View>
          ) : (
            <ScrollView
              horizontal
              showsHorizontalScrollIndicator={false}
              contentContainerStyle={styles.thumbnailsRow}
            >
              {thumbnails.map((thumb) => {
                const isSelected = selectedFace === thumb.index;
                return (
                  <TouchableOpacity
                    key={thumb.index}
                    style={[
                      styles.thumbWrapper,
                      isSelected && styles.thumbWrapperSelected,
                    ]}
                    onPress={() => {
                      console.log('[FaceSelector] Tapped face thumbnail:', thumb.index);
                      setSelectedFace(thumb.index);
                    }}
                    activeOpacity={0.75}
                  >
                    <Image
                      source={{ uri: thumb.uri }}
                      style={styles.thumbImage}
                      resizeMode="cover"
                    />
                    {isSelected && (
                      <View style={styles.checkBadge}>
                        <Text style={styles.checkText}>✓</Text>
                      </View>
                    )}
                    <Text style={styles.thumbLabel}>
                      Volto {thumb.index + 1}
                    </Text>
                  </TouchableOpacity>
                );
              })}
            </ScrollView>
          )}

          <View style={styles.buttons}>
            <TouchableOpacity
              style={[styles.button, styles.cancelButton]}
              onPress={handleCancelPress}
              activeOpacity={0.8}
            >
              <Text style={styles.cancelButtonText}>Annulla</Text>
            </TouchableOpacity>
            <TouchableOpacity
              style={[
                styles.button,
                styles.confirmButton,
                selectedFace === null && styles.confirmButtonDisabled,
              ]}
              onPress={handleConfirm}
              disabled={selectedFace === null}
              activeOpacity={0.8}
            >
              <Text style={styles.confirmButtonText}>
                {selectedFace !== null ? 'Conferma' : 'Seleziona un volto'}
              </Text>
            </TouchableOpacity>
          </View>
        </View>
      </View>
    </Modal>
  );
}

const styles = StyleSheet.create({
  overlay: {
    flex: 1,
    backgroundColor: 'rgba(0, 0, 0, 0.85)',
    justifyContent: 'center',
    alignItems: 'center',
    padding: 20,
  },
  content: {
    backgroundColor: colors.card,
    borderRadius: 24,
    padding: 24,
    width: '100%',
    maxWidth: 480,
  },
  title: {
    fontSize: 22,
    fontWeight: 'bold',
    color: colors.text,
    textAlign: 'center',
    marginBottom: 6,
  },
  subtitle: {
    fontSize: 14,
    color: colors.textSecondary,
    textAlign: 'center',
    marginBottom: 24,
    lineHeight: 20,
  },
  loadingContainer: {
    alignItems: 'center',
    paddingVertical: 32,
    gap: 12,
  },
  loadingText: {
    fontSize: 14,
    color: colors.textSecondary,
  },
  thumbnailsRow: {
    flexDirection: 'row',
    gap: 12,
    paddingHorizontal: 4,
    paddingBottom: 8,
    minWidth: '100%',
    justifyContent: 'center',
  },
  thumbWrapper: {
    alignItems: 'center',
    gap: 6,
    borderRadius: 16,
    padding: 6,
    borderWidth: 3,
    borderColor: 'transparent',
    backgroundColor: colors.cardDark,
  },
  thumbWrapperSelected: {
    borderColor: colors.secondary,
    backgroundColor: 'rgba(252, 211, 77, 0.15)',
  },
  thumbImage: {
    width: THUMB_SIZE,
    height: THUMB_SIZE,
    borderRadius: 12,
    backgroundColor: colors.backgroundDark,
  },
  checkBadge: {
    position: 'absolute',
    top: 4,
    right: 4,
    width: 26,
    height: 26,
    borderRadius: 13,
    backgroundColor: colors.secondary,
    alignItems: 'center',
    justifyContent: 'center',
  },
  checkText: {
    color: colors.background,
    fontSize: 14,
    fontWeight: 'bold',
  },
  thumbLabel: {
    fontSize: 12,
    fontWeight: '600',
    color: colors.textSecondary,
  },
  buttons: {
    flexDirection: 'row',
    gap: 12,
    marginTop: 24,
  },
  button: {
    flex: 1,
    paddingVertical: 14,
    borderRadius: 14,
    alignItems: 'center',
  },
  cancelButton: {
    backgroundColor: colors.cardDark,
    borderWidth: 1.5,
    borderColor: colors.border,
  },
  cancelButtonText: {
    fontSize: 15,
    fontWeight: '600',
    color: colors.textSecondary,
  },
  confirmButton: {
    backgroundColor: colors.secondary,
  },
  confirmButtonDisabled: {
    backgroundColor: '#555',
  },
  confirmButtonText: {
    fontSize: 15,
    fontWeight: 'bold',
    color: colors.background,
  },
});

import React from 'react';
import {
  View,
  Text,
  StyleSheet,
  ScrollView,
  TouchableOpacity,
  Image,
  ImageSourcePropType,
  Dimensions,
} from 'react-native';
import { Stack, useLocalSearchParams, useRouter } from 'expo-router';
import { SafeAreaView } from 'react-native-safe-area-context';
import { LinearGradient } from 'expo-linear-gradient';
import { colors } from '@/styles/commonStyles';

const screenWidth = Dimensions.get('window').width;

function resolveImageSource(source: string | undefined): ImageSourcePropType {
  if (!source) return { uri: '' };
  return { uri: source };
}

function parseExplanationBullets(explanation: string): string[] {
  if (!explanation) return [];
  // Split on newlines, dashes, bullets, or numbered lists
  const lines = explanation
    .split(/\n|(?:\.\s+(?=[A-Z]))|(?:[-•*]\s+)|(?:\d+\.\s+)/)
    .map((l) => l.trim())
    .filter((l) => l.length > 10);
  if (lines.length <= 1) {
    // Try splitting on periods
    return explanation
      .split(/\.\s+/)
      .map((l) => l.trim())
      .filter((l) => l.length > 10)
      .map((l) => (l.endsWith('.') ? l : l + '.'));
  }
  return lines;
}

interface SimilarityBarProps {
  label: string;
  value: number;
  isWinner: boolean;
  imageUri?: string;
}

function SimilarityBar({ label, value, isWinner, imageUri }: SimilarityBarProps) {
  const pct = Math.min(100, Math.max(0, Number(value) || 0));
  const pctText = pct.toFixed(0) + '%';
  const barColor = isWinner ? colors.secondary : colors.textSecondary;
  const imageSource = resolveImageSource(imageUri);

  return (
    <View style={barStyles.container}>
      <View style={barStyles.header}>
        {imageUri ? (
          <Image source={imageSource} style={barStyles.avatar} resizeMode="cover" />
        ) : (
          <View style={[barStyles.avatar, { backgroundColor: colors.cardDark }]} />
        )}
        <View style={barStyles.labelRow}>
          <Text style={barStyles.label} numberOfLines={1}>
            {label}
          </Text>
          {isWinner && <Text style={barStyles.winnerTag}>VINCITORE</Text>}
        </View>
        <Text style={[barStyles.pctText, { color: barColor }]}>{pctText}</Text>
      </View>
      <View style={barStyles.track}>
        <View style={[barStyles.fill, { width: `${pct}%`, backgroundColor: barColor }]} />
      </View>
    </View>
  );
}

const barStyles = StyleSheet.create({
  container: {
    marginBottom: 16,
  },
  header: {
    flexDirection: 'row',
    alignItems: 'center',
    marginBottom: 8,
    gap: 10,
  },
  avatar: {
    width: 44,
    height: 44,
    borderRadius: 22,
    backgroundColor: colors.card,
  },
  labelRow: {
    flex: 1,
    gap: 2,
  },
  label: {
    fontSize: 15,
    fontWeight: '700',
    color: colors.text,
  },
  winnerTag: {
    fontSize: 10,
    fontWeight: 'bold',
    color: colors.background,
    backgroundColor: colors.secondary,
    paddingHorizontal: 6,
    paddingVertical: 2,
    borderRadius: 4,
    alignSelf: 'flex-start',
  },
  pctText: {
    fontSize: 20,
    fontWeight: 'bold',
  },
  track: {
    height: 10,
    backgroundColor: colors.cardDark,
    borderRadius: 5,
    overflow: 'hidden',
  },
  fill: {
    height: '100%',
    borderRadius: 5,
  },
});

export default function ComparisonResultScreen() {
  const params = useLocalSearchParams<{
    winner: string;
    similarity1: string;
    similarity2: string;
    explanation: string;
    name1: string;
    name2: string;
    mainUri: string;
    comp1Uri: string;
    comp2Uri: string;
  }>();
  const router = useRouter();

  const winner = Number(params.winner) || 1;
  const similarity1 = Number(params.similarity1) || 0;
  const similarity2 = Number(params.similarity2) || 0;
  const explanation = params.explanation || '';
  const name1 = params.name1 || 'Foto 1';
  const name2 = params.name2 || 'Foto 2';
  const mainUri = params.mainUri || '';
  const comp1Uri = params.comp1Uri || '';
  const comp2Uri = params.comp2Uri || '';

  const isWinner1 = winner === 1;
  const isWinner2 = winner === 2;

  const winnerName = isWinner1 ? name1 : name2;
  const winnerUri = isWinner1 ? comp1Uri : comp2Uri;
  const winnerSim = isWinner1 ? similarity1 : similarity2;
  const loserName = isWinner1 ? name2 : name1;
  const loserUri = isWinner1 ? comp2Uri : comp1Uri;
  const loserSim = isWinner1 ? similarity2 : similarity1;

  const bullets = parseExplanationBullets(explanation);

  const mainImageSource = resolveImageSource(mainUri);
  const winnerImageSource = resolveImageSource(winnerUri);
  const loserImageSource = resolveImageSource(loserUri);

  const winnerSimText = winnerSim.toFixed(0) + '%';
  const loserSimText = loserSim.toFixed(0) + '%';

  const handleNewAnalysis = () => {
    console.log('[ComparisonResult] User tapped Nuova analisi');
    router.replace('/(tabs)/(home)');
  };

  return (
    <LinearGradient
      colors={[colors.background, colors.backgroundDark]}
      style={styles.gradient}
      start={{ x: 0, y: 0 }}
      end={{ x: 1, y: 1 }}
    >
      <SafeAreaView style={styles.safeArea} edges={['top', 'bottom']}>
        <Stack.Screen options={{ headerShown: false }} />

        <ScrollView
          style={styles.scroll}
          contentContainerStyle={styles.scrollContent}
          showsVerticalScrollIndicator={false}
        >
          {/* ── Header ── */}
          <View style={styles.headerRow}>
            <TouchableOpacity
              style={styles.backBtn}
              onPress={() => {
                console.log('[ComparisonResult] User tapped back');
                router.back();
              }}
              activeOpacity={0.8}
            >
              <Text style={styles.backBtnText}>← Indietro</Text>
            </TouchableOpacity>
            <Text style={styles.screenTitle}>GARA</Text>
            <View style={{ width: 80 }} />
          </View>

          {/* ── Main photo ── */}
          <View style={styles.mainPhotoSection}>
            <Text style={styles.sectionLabel}>Foto principale</Text>
            <View style={styles.mainPhotoWrapper}>
              <Image
                source={mainImageSource}
                style={styles.mainPhoto}
                resizeMode="cover"
              />
              <LinearGradient
                colors={['transparent', 'rgba(0,0,0,0.5)']}
                style={styles.mainPhotoGradient}
              />
            </View>
          </View>

          {/* ── VS row ── */}
          <View style={styles.vsRow}>
            <View style={styles.vsDividerLine} />
            <Text style={styles.vsText}>VS</Text>
            <View style={styles.vsDividerLine} />
          </View>

          {/* ── Contenders side by side ── */}
          <View style={styles.contendersRow}>
            {/* Contender 1 */}
            <View style={[styles.contenderCard, isWinner1 && styles.contenderCardWinner]}>
              {isWinner1 && (
                <View style={styles.crownBadge}>
                  <Text style={styles.crownEmoji}>👑</Text>
                </View>
              )}
              <Image
                source={resolveImageSource(comp1Uri)}
                style={styles.contenderImage}
                resizeMode="cover"
              />
              <Text style={styles.contenderName} numberOfLines={1}>
                {name1}
              </Text>
              <Text style={[styles.contenderSim, { color: isWinner1 ? colors.secondary : colors.textSecondary }]}>
                {similarity1.toFixed(0)}%
              </Text>
              {isWinner1 && <Text style={styles.winnerLabel}>VINCITORE</Text>}
            </View>

            {/* Contender 2 */}
            <View style={[styles.contenderCard, isWinner2 && styles.contenderCardWinner]}>
              {isWinner2 && (
                <View style={styles.crownBadge}>
                  <Text style={styles.crownEmoji}>👑</Text>
                </View>
              )}
              <Image
                source={resolveImageSource(comp2Uri)}
                style={styles.contenderImage}
                resizeMode="cover"
              />
              <Text style={styles.contenderName} numberOfLines={1}>
                {name2}
              </Text>
              <Text style={[styles.contenderSim, { color: isWinner2 ? colors.secondary : colors.textSecondary }]}>
                {similarity2.toFixed(0)}%
              </Text>
              {isWinner2 && <Text style={styles.winnerLabel}>VINCITORE</Text>}
            </View>
          </View>

          {/* ── Winner announcement ── */}
          <LinearGradient
            colors={[colors.secondary, colors.accent]}
            start={{ x: 0, y: 0 }}
            end={{ x: 1, y: 0 }}
            style={styles.winnerBanner}
          >
            <Text style={styles.winnerBannerEmoji}>🏆</Text>
            <View style={styles.winnerBannerText}>
              <Text style={styles.winnerBannerLabel}>Somiglia di più a</Text>
              <Text style={styles.winnerBannerName}>{winnerName}</Text>
            </View>
            <Text style={styles.winnerBannerPct}>{winnerSimText}</Text>
          </LinearGradient>

          {/* ── Similarity bars ── */}
          <View style={styles.card}>
            <Text style={styles.cardTitle}>Somiglianza</Text>
            <SimilarityBar
              label={name1}
              value={similarity1}
              isWinner={isWinner1}
              imageUri={comp1Uri}
            />
            <SimilarityBar
              label={name2}
              value={similarity2}
              isWinner={isWinner2}
              imageUri={comp2Uri}
            />
          </View>

          {/* ── Explanation bullets ── */}
          {bullets.length > 0 && (
            <View style={styles.card}>
              <Text style={styles.cardTitle}>Analisi dettagliata</Text>
              {bullets.map((bullet, i) => (
                <View key={i} style={styles.bulletRow}>
                  <View style={styles.bulletDot} />
                  <Text style={styles.bulletText}>{bullet}</Text>
                </View>
              ))}
            </View>
          )}

          {/* ── Raw explanation fallback if no bullets ── */}
          {bullets.length === 0 && explanation.length > 0 && (
            <View style={styles.card}>
              <Text style={styles.cardTitle}>Spiegazione</Text>
              <Text style={styles.explanationText}>{explanation}</Text>
            </View>
          )}

          {/* ── Nuova analisi button ── */}
          <TouchableOpacity
            style={styles.newAnalysisBtn}
            onPress={handleNewAnalysis}
            activeOpacity={0.85}
          >
            <LinearGradient
              colors={[colors.primary, colors.primaryDark]}
              start={{ x: 0, y: 0 }}
              end={{ x: 1, y: 0 }}
              style={styles.newAnalysisGradient}
            >
              <Text style={styles.newAnalysisBtnEmoji}>🔄</Text>
              <Text style={styles.newAnalysisBtnText}>Nuova analisi</Text>
            </LinearGradient>
          </TouchableOpacity>

          <View style={{ height: 40 }} />
        </ScrollView>
      </SafeAreaView>
    </LinearGradient>
  );
}

const CONTENDER_IMG = (screenWidth - 40 - 12) / 2;

const styles = StyleSheet.create({
  gradient: { flex: 1 },
  safeArea: { flex: 1 },
  scroll: { flex: 1 },
  scrollContent: { padding: 20 },

  // Header
  headerRow: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'space-between',
    marginBottom: 24,
  },
  backBtn: {
    paddingVertical: 8,
    paddingHorizontal: 4,
    width: 80,
  },
  backBtnText: {
    fontSize: 15,
    fontWeight: '600',
    color: colors.textSecondary,
  },
  screenTitle: {
    fontSize: 22,
    fontWeight: 'bold',
    color: colors.text,
    letterSpacing: 3,
  },

  // Main photo
  mainPhotoSection: {
    alignItems: 'center',
    marginBottom: 16,
  },
  sectionLabel: {
    fontSize: 13,
    fontWeight: '600',
    color: colors.textSecondary,
    marginBottom: 10,
    textTransform: 'uppercase',
    letterSpacing: 1,
  },
  mainPhotoWrapper: {
    borderRadius: 20,
    overflow: 'hidden',
    borderWidth: 3,
    borderColor: colors.secondary,
  },
  mainPhoto: {
